"""云端音乐库元数据

每个成员是一首剪映云端音乐, 携带其 id, 标题与时长(微秒),
时长由秒换算而来, 构造 `CloudMusicMaterial` 时可直接作为默认时长使用。
"""
from .effect_meta import EffectEnum, MusicMeta

class CloudMusicType(EffectEnum):
    """剪映云端音乐库枚举

    成员名由音乐标题生成, 空格与标点替换为下划线;
    `from_name` 支持按原始标题查找。
    """

    @classmethod
    def from_name(cls, name: str) -> "CloudMusicType":
        """根据音乐标题获取云端音乐, 优先匹配原始标题"""
        norm = name.lower().replace(" ", "").replace("_", "")
        for music in cls:
            if music.value.title.lower().replace(" ", "").replace("_", "") == norm:
                return music
        return super().from_name(name)

